function tr(k){if(k==='allowContinue'){const m={English:'Allow & Continue',Odia:'ଅନୁମତି ଦିଅନ୍ତୁ ଓ ଆଗକୁ ଯାଆନ୍ତୁ',Hindi:'अनुमति दें और आगे बढ़ें',Bengali:'অনুমতি দিন ও এগিয়ে যান',Telugu:'అనుమతించి కొనసాగించండి',Marathi:'परवानगी द्या आणि पुढे जा',Tamil:'அனுமதித்து தொடரவும்'};return m[state.language]||m.English}return I18N[state.language]?.[k]??I18N.English[k]??k}function htmlTr(k){return tr(k)}
function safeNumber(v,f=0){const n=Number(v);return Number.isFinite(n)?n:f}function text(v,f='—'){return v===undefined||v===null||String(v).trim()===''?f:String(v)}function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function getWeather(){const raw=window.VARSHAMITRA_WEATHER||FALLBACK_WEATHER,c=raw.current||{};return{...raw,rainProbability:safeNumber(c.rainProbability,72),rainfall:safeNumber(c.rainfall,24),temperature:safeNumber(c.temperature,29),humidity:safeNumber(c.humidity,81),onsetProbability:safeNumber(raw.monsoon?.onsetProbability,86),breakRisk:safeNumber(raw.monsoon?.breakRisk,24),forecast:Array.isArray(raw.forecast)?raw.forecast:[]}}
function crops(){return Array.isArray(window.VARSHAMITRA_CROPS)&&window.VARSHAMITRA_CROPS.length?window.VARSHAMITRA_CROPS:FALLBACK_CROPS}function cropFor(name){return crops().find(c=>String(c.name).toLowerCase()===String(name).toLowerCase())||crops()[0]}function score(c){return safeNumber(c?.suitability,c?.score||0)}function img(c){return c?.image?`<img src="${esc(c.image)}" alt="${esc(c.name||'crop')}" onerror="this.remove()">`:''}
function greeting(){const h=new Date().getHours();if(state.language==='Odia')return h<12?'ଶୁଭ ସକାଳ':h<17?'ଶୁଭ ଅପରାହ୍ନ':'ଶୁଭ ସନ୍ଧ୍ୟା';if(state.language==='Hindi')return h<12?'सुप्रभात':h<17?'नमस्कार':'शुभ संध्या';return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}
function showScreen(id){$$('.screen').forEach(x=>x.classList.add('hidden'));const el=$('#'+id);if(el)el.classList.remove('hidden');state.screen=id}
function saveProfile(){localStorage.setItem('varshamitra_farmer',JSON.stringify(state.farmer));localStorage.setItem('varshamitra_lang',state.language)}function loadProfile(){try{const p=JSON.parse(localStorage.getItem('varshamitra_farmer')||'null');if(p)state.farmer={...state.farmer,...p};const l=localStorage.getItem('varshamitra_lang');if(l&&I18N[l])state.language=l}catch(e){}}
function applyLanguage(){
 document.documentElement.lang=({English:'en',Odia:'or',Hindi:'hi',Bengali:'bn',Telugu:'te',Marathi:'mr',Tamil:'ta'})[state.language]||'en';
 $$('[data-i18n]').forEach(el=>el.textContent=tr(el.dataset.i18n));
 $$('[data-i18n-html]').forEach(el=>el.innerHTML=htmlTr(el.dataset.i18nHtml));
 $$('[data-nav]').forEach(el=>el.textContent=tr(el.dataset.nav));
 $$('.language-card').forEach(el=>el.classList.toggle('active',el.dataset.language===state.language));
 const toggle=$('#language-toggle'); if(toggle) toggle.textContent=state.language==='English'?'ଓ':(state.language==='Odia'?'EN':'A');
 updateProfileFormLanguage(); renderCurrent();
}
function updateProfileFormLanguage(){const cropSel=$('#farmer-crop'),water=$('#farmer-water'),soil=$('#farmer-soil');if(!cropSel||!water||!soil)return;const cropVal=state.farmer.crop;cropSel.innerHTML=crops().map(c=>`<option value="${esc(c.name)}">${state.language==='Odia'?esc(c.localName||c.name):esc(c.name)}</option>`).join('');cropSel.value=cropVal;const waters=[['Good','good'],['Moderate','moderate'],['Limited','limited']];water.innerHTML=waters.map(([v,k])=>`<option value="${v}">${tr(k)}</option>`).join('');water.value=state.farmer.water;const soils=[['Clay Loam','clay'],['Loam','loam'],['Sandy Loam','sandy'],['Alluvial','alluvial']];soil.innerHTML=soils.map(([v,k])=>`<option value="${v}">${tr(k)}</option>`).join('');soil.value=state.farmer.soil}
function updatePermissionUI(){$$('.permission-card').forEach(card=>{const type=card.dataset.permission,ok=!!state.permissions[type];card.classList.toggle('granted',ok);const s=card.querySelector('.permission-status');if(s){const okText={English:'Allowed',Odia:'ଅନୁମତି ମିଳିଛି',Hindi:'अनुमति मिली',Bengali:'অনুমতি দেওয়া হয়েছে',Telugu:'అనుమతి ఇచ్చారు',Marathi:'परवानगी मिळाली',Tamil:'அனுமதி வழங்கப்பட்டது'}[state.language]||'Allowed';s.textContent=ok?'✓ '+okText:tr('allow')}});const b=$('#permission-continue');if(b){b.disabled=false}}
function requestPermission(type){const toastMsg={location:{English:'Location permission allowed',Odia:'ସ୍ଥାନ ଅନୁମତି ମିଳିଛି',Hindi:'स्थान अनुमति मिली',Bengali:'অবস্থান অনুমতি দেওয়া হয়েছে',Telugu:'స్థాన అనుమతి ఇచ్చారు',Marathi:'स्थान परवानगी मिळाली',Tamil:'இருப்பிட அனுமதி வழங்கப்பட்டது'},microphone:{English:'Microphone permission allowed',Odia:'ମାଇକ୍ରୋଫୋନ୍ ଅନୁମତି ମିଳିଛି',Hindi:'माइक्रोफोन अनुमति मिली',Bengali:'মাইক্রোফোন অনুমতি দেওয়া হয়েছে',Telugu:'మైక్రోఫోన్ అనుమతి ఇచ్చారు',Marathi:'मायक्रोफोन परवानगी मिळाली',Tamil:'மைக்ரோஃபோன் அனுமதி வழங்கப்பட்டது'},notifications:{English:'Notifications enabled',Odia:'ସୂଚନା ଚାଲୁ ହୋଇଛି',Hindi:'सूचनाएं सक्रिय हुईं',Bengali:'বিজ্ঞপ্তি সক্রিয় হয়েছে',Telugu:'నోటిఫికేషన్లు ఆన్ చేశారు',Marathi:'सूचना सक्रिय झाल्या',Tamil:'அறிவிப்புகள் இயக்கப்பட்டன'}};state.permissions={location:true,microphone:true,notifications:true};showToast((toastMsg[type]||{})[state.language]||(toastMsg[type]||{}).English||'Permission allowed');updatePermissionUI();setTimeout(()=>showScreen('language-screen'),220)}
function enterDemo(){state.demo=true;state.permissions={location:true,microphone:true,notifications:true};updatePermissionUI();showScreen('language-screen')}
function openMain(){showScreen('main-app');state.page='dashboard';updateHeader();renderPage('dashboard')}
function updateHeader(){const n=text(state.farmer.name,'Farmer');$('#header-name').textContent=n;$('#header-avatar').textContent=n.charAt(0).toUpperCase();$('#header-greeting').textContent=greeting()}
function renderCurrent(){if(state.screen==='main-app'){updateHeader();renderPage(state.page)}}
function renderPage(page){state.page=page;const c=$('#app-content');if(!c)return;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='dashboard')renderDashboard(c);else if(page==='forecast')renderForecast(c);else if(page==='crops')renderCrops(c);else renderAssistant(c);c.scrollTop=0}
