function cropAdvice(c){if(state.language==='Odia')return c.adviceOdia||c.advice;return CROP_ADVICE[state.language]||c.advice}
function dayName(day){const maps={Odia:{Sun:'ରବି',Mon:'ସୋମ',Tue:'ମଙ୍ଗଳ',Wed:'ବୁଧ',Thu:'ଗୁରୁ',Fri:'ଶୁକ୍ର',Sat:'ଶନି',Today:'ଆଜି'},Hindi:{Sun:'रवि',Mon:'सोम',Tue:'मंगल',Wed:'बुध',Thu:'गुरु',Fri:'शुक्र',Sat:'शनि',Today:'आज'},Bengali:{Sun:'রবি',Mon:'সোম',Tue:'মঙ্গল',Wed:'বুধ',Thu:'বৃহস্পতি',Fri:'শুক্র',Sat:'শনি',Today:'আজ'},Telugu:{Sun:'ఆది',Mon:'సోమ',Tue:'మంగళ',Wed:'బుధ',Thu:'గురు',Fri:'శుక్ర',Sat:'శని',Today:'ఈరోజు'},Marathi:{Sun:'रवि',Mon:'सोम',Tue:'मंगळ',Wed:'बुध',Thu:'गुरु',Fri:'शुक्र',Sat:'शनि',Today:'आज'},Tamil:{Sun:'ஞாயிறு',Mon:'திங்கள்',Tue:'செவ்வாய்',Wed:'புதன்',Thu:'வியாழன்',Fri:'வெள்ளி',Sat:'சனி',Today:'இன்று'}};return maps[state.language]?.[day]||day}
function renderDashboard(c){const w=getWeather(),crop=cropFor(state.farmer.crop),lc=localizedCrop(crop),od=state.language==='Odia';const status=GENERIC_LOCAL.rainStatus[state.language]||w.status;const action=state.language==='Odia'?(w.todayActionOdia||w.todayAction):w.todayAction;c.innerHTML=`<div class="page-enter"><div class="team-strip"><img src="assets/team-logo.png" alt="Code Raiders"><div><strong>Code Raiders <b>— VarshaMitra</b></strong><span>SIH26086 · ${tr('teamLine')}</span></div></div><div class="location-card"><span class="small-label">${tr('yourFarmLocation')}</span><h2 class="location-title">📍 ${esc(state.farmer.location)}</h2><div class="live-row"><i class="live-dot"></i> ${tr('live')} · ${esc(status)}</div></div><div class="weather-hero"><div class="weather-top"><div><span class="weather-status">🌧 ${tr('rainIntelligence')}</span><h1>${w.rainProbability}%</h1><p>${tr('rainProbability')}</p></div><div class="weather-icon">🌦️</div></div><div class="weather-divider"></div><div class="weather-stats"><div class="weather-stat"><strong>${w.rainfall} mm</strong><span>${tr('expectedRain')}</span></div><div class="weather-stat"><strong>${w.temperature}°</strong><span>${tr('temperature')}</span></div><div class="weather-stat"><strong>${w.humidity}%</strong><span>${tr('humidity')}</span></div></div></div><div class="section-heading"><div><span>${tr('monsoon')}</span><h3>${tr('whatNext')}</h3></div><button onclick="renderPage('forecast')">${tr('viewAll')}</button></div><div class="intelligence-grid"><div class="intelligence-card"><span class="intel-icon">🌧️</span><small>${tr('onset')}</small><strong>${w.onsetProbability}%</strong><p>${esc(GENERIC_LOCAL.onset[state.language])} · ${esc(GENERIC_LOCAL.onsetStatus[state.language])}</p></div><div class="intelligence-card warning"><span class="intel-icon">☀️</span><small>${tr('breakRisk')}</small><strong>${w.breakRisk}%</strong><p>${esc(GENERIC_LOCAL.break[state.language])}</p></div></div><div class="section-heading"><div><span>${tr('yourCrop')}</span><h3>${esc(lc.name)}</h3></div><span class="crop-score">${score(crop)}% ${tr('match')}</span></div><div class="crop-summary" onclick="openCrop('${esc(crop.id)}')" style="cursor:pointer" title="${esc(tr('viewCrop'))}"><div class="crop-summary-image">${img(crop)}${crop.image?'':'🌾'}</div><div class="crop-summary-info"><strong>${esc(lc.name)}</strong><p>${esc(state.language==='Odia'?(crop.reasonOdia||crop.reason):crop.reason)}</p><span>${tr('waterAccess')} · ${esc(lc.water)}</span></div></div><button class="crop-summary-action" onclick="openCrop('${esc(crop.id)}')"><span>🌾</span> ${tr('viewCrop')}</button><div class="action-banner"><div class="action-icon">✓</div><div><small>${tr('todayAction')}</small><strong>${esc(action)}</strong></div></div><button class="ai-banner" onclick="renderPage('assistant')"><div class="ai-symbol">✦</div><div><strong>${tr('askAI')}</strong><p>${tr('aiSub')}</p></div><span>→</span></button></div>`}
function renderForecast(c){const w=getWeather();const rows=w.forecast.map(x=>`<div class="forecast-row"><div><strong>${esc(dayName(x.day))}</strong><small>${esc(x.date)}</small></div><div class="rain-bar"><i style="width:${Math.min(100,Math.max(0,safeNumber(x.rainProbability)))}%"></i></div><span class="rain-value">${safeNumber(x.rainProbability)}%</span></div>`).join('');const onset=GENERIC_LOCAL.onsetStatus[state.language]||w.monsoon.onsetStatus;const signal=state.language==='English'?'Onset signal':state.language==='Odia'?'ଆରମ୍ଭ ସଙ୍କେତ':state.language==='Hindi'?'शुरुआत संकेत':state.language==='Bengali'?'শুরুর সংকেত':state.language==='Telugu'?'ప్రారంభ సంకేతం':state.language==='Marathi'?'सुरुवातीचा संकेत':'தொடக்க அறிகுறி';const br=tr('breakRisk');const note=state.language==='English'?'Use these prototype indicators together with local field conditions before taking action.':state.language==='Odia'?'କ୍ଷେତର ପରିସ୍ଥିତି ସହ ଏହି ସଙ୍କେତଗୁଡ଼ିକୁ ମିଶାଇ ନିଷ୍ପତ୍ତି ନିଅନ୍ତୁ।':state.language==='Hindi'?'कार्रवाई से पहले इन प्रोटोटाइप संकेतों को स्थानीय खेत की स्थिति के साथ देखें।':state.language==='Bengali'?'কাজ করার আগে এই প্রোটোটাইপ সংকেতগুলিকে স্থানীয় মাঠের অবস্থার সঙ্গে মিলিয়ে দেখুন।':state.language==='Telugu'?'చర్యకు ముందు ఈ ప్రోటోటైప్ సూచనలను స్థానిక పొలం పరిస్థితులతో కలిపి చూడండి.':state.language==='Marathi'?'कारवाईपूर्वी हे प्रोटोटाइप संकेत स्थानिक शेताच्या स्थितीसोबत पहा.':'கृती करण्यापूर्वी या संकेतांना स्थानिक शेत परिस्थितीसोबत पहा.';
const allCrops=[...crops()].sort((a,b)=>score(b)-score(a));
const seasonLabel=state.language==='Odia'?'ଏହି ବର୍ଷା ଋତୁ ପାଇଁ ସର୍ବୋତ୍ତମ ଫସଲ':state.language==='Hindi'?'इस वर्षा ऋतु के लिए सर्वोत्तम फसलें':state.language==='Bengali'?'এই বর্ষা মৌসুমের জন্য সেরা ফসল':state.language==='Telugu'?'ఈ వర్షాకాలానికి అనుకూల పంటలు':state.language==='Marathi'?'या पावसाळी हंगामासाठी सर्वोत्तम पिके':state.language==='Tamil'?'இந்த மழை பருவத்திற்கான சிறந்த பயிர்கள்':'Best crops for this rainfall season';
const cropRecs=allCrops.map(x=>{const lc=localizedCrop(x);const sc=score(x);const isBest=sc>=80;return `<div class="season-crop-card${isBest?' best-season':''}" onclick="openCrop('${esc(x.id)}')" style="cursor:pointer" title="${esc(tr('viewCrop'))}"><div class="season-crop-icon">${x.image?`<img src="${x.image}" alt="${x.name}" style="width:100%;height:100%;object-fit:cover;border-radius:14px" onerror="this.style.display='none'">`:''}<span style="${x.image?'display:none':''};font-size:22px">${esc(x.icon||'🌱')}</span></div><div class="season-crop-body"><strong>${esc(lc.name)}</strong>${isBest?`<span class="best-badge">★ Best pick</span>`:''}<p>${esc(cropReason(x))}</p><div class="season-tags"><span>🌧 ${sc}% rain match</span><span>💧 ${esc(lc.water)} water</span><span>🌱 ${esc(cropStatus(x))}</span></div></div><div class="season-crop-pct" style="color:${isBest?'var(--accent)':'var(--text2)'}">${sc}%</div></div>`}).join('');
c.innerHTML=`<div class="page-enter"><div class="page-title"><span>${tr('monsoon')}</span><h2>${tr('next7')}</h2><p>${tr('planAround')}</p></div><div class="forecast-main-card"><div class="forecast-card-top"><div><small>${tr('next7')}</small><strong>${tr('rainProbabilityShort')}</strong></div><span class="forecast-now">${w.rainProbability}%</span></div><div class="forecast-list">${rows||'<p>—</p>'}</div></div><div class="intel-wide"><h3>🌧 ${esc(onset)}</h3><p>${esc(signal)} ${w.onsetProbability}% · ${esc(br)} ${w.breakRisk}%. ${esc(note)}</p></div><div class="season-section"><div class="section-heading"><div><span>SEASON PICKS</span><h3>${esc(seasonLabel)}</h3></div></div><div class="season-crops-list">${cropRecs}</div></div></div>`}
function renderCrops(c){const cards=crops().map(x=>{const lc=localizedCrop(x);return `<article class="crop-card"><div class="crop-card-image">${img(x)}${x.image?'':esc(x.icon||'🌱')}</div><div><h3>${esc(lc.name)}</h3><p>${esc(cropReason(x))}</p><span class="crop-tag">${esc(cropStatus(x))} · ${tr('waterAccess')} ${esc(cropWater(x))}</span></div><div class="crop-percent">${score(x)}%</div><button onclick="openCrop('${esc(x.id)}')">${tr('viewCrop')}</button></article>`}).join('');c.innerHTML=`<div class="page-enter"><div class="page-title"><span>${tr('cropIntelligence')}</span><h2>${tr('whatGrow')}</h2><p>${tr('cropSub')}</p></div><div class="crop-list">${cards}</div></div>`}
function openCrop(id){const prev=document.getElementById('crop-detail-modal');if(prev)prev.remove();const x=crops().find(c=>String(c.id).toLowerCase()===String(id).toLowerCase())||crops()[0];const lc=localizedCrop(x);const w=getWeather();const s=score(x);
const CROP_DETAIL={Paddy:{growSteps:['Land preparation: Plough field 2–3 times. Puddling recommended for clay soils.','Seed selection: Use certified variety seeds. Soak for 24h before sowing.','Nursery: Sow seeds in nursery bed. Transplant 20–25 day seedlings.','Transplanting: Maintain 20×20 cm spacing. Keep 5 cm water depth.','Harvest: Ready in 100–150 days when 80% grains turn golden.'],waterGuide:[{week:'Week 1–2',action:'Flood field 5 cm after transplant',when:'Rain < 30%: irrigate daily'},{week:'Week 3–8',action:'Maintain 3–5 cm standing water',when:'Rain > 60%: drain excess'},{week:'Week 9–12',action:'Reduce water at panicle stage',when:'Allow field to dry 1–2 weeks before harvest'}],fertGuide:[{stage:'Basal (before transplant)',npk:'40–60 kg/ha DAP + 40 kg MOP'},{stage:'21 days after transplant',npk:'30 kg/ha Urea'},{stage:'45 days after transplant',npk:'30 kg/ha Urea'}],weatherTip:w.rainProbability>60?'Heavy rain expected — ensure drainage channels are open to prevent waterlogging.':w.rainProbability>30?'Moderate rain ahead — good for transplanting. Monitor field water levels.':'Low rain expected — plan supplemental irrigation for critical crop stages.'},Maize:{growSteps:['Field prep: Deep plough and level. Apply FYM 10 t/ha before sowing.','Sowing: Dibbling method, 2 seeds/hill. Depth 4–5 cm.','Thinning: Remove weaker plant after 2 weeks, keep 1 plant/hill.','Earthing up: At 30–35 days to support stalk and control weeds.','Harvest: Dry husks and black-layer formation signal maturity.'],waterGuide:[{week:'Emergence (0–10 days)',action:'Light irrigation after sowing',when:'Rain < 20%: irrigate every 4 days'},{week:'Vegetative (11–40 days)',action:'Irrigate at critical stages',when:'Rain > 50%: skip irrigation'},{week:'Silking/grain fill (41–75 days)',action:'Critical stage — keep moist',when:'Never let soil dry at this stage'}],fertGuide:[{stage:'At sowing',npk:'60 kg/ha DAP + 30 kg MOP'},{stage:'30 days (V6 stage)',npk:'40 kg/ha Urea top-dress'},{stage:'50 days (tasseling)',npk:'30 kg/ha Urea'}],weatherTip:w.rainProbability>70?'Excess rain risk — ensure good drainage to prevent stalk rot.':w.rainProbability>35?'Good rain outlook for maize. Check for fall armyworm after heavy showers.':'Moisture stress possible — irrigate at silking stage to protect yield.'},Pulses:{growSteps:['Seed treatment: Treat with Rhizobium culture for better nitrogen fixation.','Sowing: Row sowing at 30–45 cm spacing. Seed depth 3–4 cm.','Weed control: One hand-weeding at 20–25 days after sowing.','Pest watch: Check for pod borer 40–60 days after sowing.','Harvest: Pick when 70–80% pods turn brown/dry.'],waterGuide:[{week:'Germination (0–7 days)',action:'Light moisture essential',when:'Rain < 15%: one light irrigation'},{week:'Flowering (30–45 days)',action:'Critical water need',when:'Irrigate if no rain for 7+ days'},{week:'Pod fill (45–60 days)',action:'Moderate moisture',when:'Avoid waterlogging — drain immediately'}],fertGuide:[{stage:'At sowing (basal)',npk:'20 kg/ha DAP + 20 kg MOP'},{stage:'30 days (flowering)',npk:'10 kg/ha Urea only if leaves pale'},{stage:'Foliar spray',npk:'2% DAP foliar at pod initiation'}],weatherTip:w.rainProbability>65?'Heavy rain harmful for pulses — raise beds and clear drainage urgently.':w.rainProbability>30?'Moderate rain suitable. Ensure well-drained soil to avoid root rot.':'Low rain is good for ripening pulses. Final irrigation 10 days before harvest.'}};
const detail=CROP_DETAIL[x.name]||CROP_DETAIL.Paddy;
const LABELS={English:{back:'← Back',how:'🌱 How to Cultivate',water:'💧 Watering Schedule',fert:'🧪 Fertilization Guide'},Odia:{back:'← ଫେରନ୍ତୁ',how:'🌱 କିପରି ଚାଷ କରିବେ',water:'💧 ଜଳସେଚନ ସମୟସୂଚୀ',fert:'🧪 ସାର ପ୍ରୟୋଗ ମାର୍ଗଦର୍ଶିକା'},Hindi:{back:'← वापस',how:'🌱 खेती कैसे करें',water:'💧 सिंचाई समय-सारिणी',fert:'🧪 उर्वरक मार्गदर्शन'},Bengali:{back:'← ফিরে যান',how:'🌱 কীভাবে চাষ করবেন',water:'💧 জলসেচনের সময়সূচী',fert:'🧪 সার প্রয়োগ গাইড'},Telugu:{back:'← వెనుకకు',how:'🌱 సాగు చేసే విధానం',water:'💧 నీటి పారుదల షెడ్యూల్',fert:'🧪 ఎరువుల మార్గదర్శి'},Marathi:{back:'← मागे',how:'🌱 लागवड कशी करावी',water:'💧 पाणी व्यवस्थापन वेळापत्रक',fert:'🧪 खत व्यवस्थापन मार्गदर्शिका'},Tamil:{back:'← பின்செல்',how:'🌱 எப்படி பயிரிடுவது',water:'💧 பாசன அட்டவணை',fert:'🧪 உர மேலாண்மை வழிகாட்டி'}};
const lbl=LABELS[state.language]||LABELS.English;
const stepsHtml=detail.growSteps.map((s,i)=>`<div class="detail-step"><span class="step-num">${i+1}</span><p>${esc(s)}</p></div>`).join('');
const waterHtml=detail.waterGuide.map(w=>`<div class="detail-water-row"><div><strong>${esc(w.week)}</strong><p>${esc(w.action)}</p></div><span class="water-tip">${esc(w.when)}</span></div>`).join('');
const fertHtml=detail.fertGuide.map(f=>`<div class="detail-fert-row"><span class="fert-stage">${esc(f.stage)}</span><span class="fert-npk">${esc(f.npk)}</span></div>`).join('');
const modal=document.createElement('div');modal.className='crop-detail-modal';modal.id='crop-detail-modal';
modal.innerHTML=`<div class="crop-detail-sheet"><div class="crop-detail-header"><button class="detail-back" onclick="document.getElementById('crop-detail-modal').remove()">${esc(lbl.back)}</button><h2>${esc(lc.name)}</h2><span class="crop-score">${s}% match</span></div><div class="crop-detail-body"><div class="detail-hero"><div class="detail-hero-icon">${img(x)}${x.image?'':esc(x.icon||'🌱')}</div><div><p class="detail-reason">${esc(cropReason(x))}</p><div class="detail-badges"><span>💧 ${esc(lc.water)} water</span><span>🌱 ${esc(cropStatus(x))}</span></div></div></div><div class="detail-weather-tip ${w.rainProbability>60?'tip-warn':w.rainProbability>30?'tip-ok':'tip-dry'}"><span>${w.rainProbability>60?'⚠️':w.rainProbability>30?'✅':'🌥'}</span><p>${esc(detail.weatherTip)}</p></div><div class="detail-section"><h3>${esc(lbl.how)}</h3>${stepsHtml}</div><div class="detail-section"><h3>${esc(lbl.water)}</h3>${waterHtml}</div><div class="detail-section"><h3>${esc(lbl.fert)}</h3>${fertHtml}</div></div></div>`;
(document.querySelector(".phone-bezel")||document.body).appendChild(modal);modal.onclick=e=>{if(e.target===modal)modal.remove()}}
let chat=[];
const AI_GREETING={English:'Namaste {name}! I am your AI Krishi Saathi. Ask me about rain, your crop, sowing, drainage or farm planning.',Odia:'ନମସ୍କାର {name}! ମୁଁ ଆପଣଙ୍କ AI କୃଷି ସାଥୀ। ବର୍ଷା, ଫସଲ, ବୁଣା, ଜଳ ନିଷ୍କାସନ କିମ୍ବା ଚାଷ ଯୋଜନା ବିଷୟରେ ପଚାରନ୍ତୁ।',Hindi:'नमस्ते {name}! मैं आपका AI कृषि साथी हूं। बारिश, फसल, बुवाई, जल निकासी या खेती की योजना के बारे में पूछें।',Bengali:'নমস্কার {name}! আমি আপনার AI কৃষি সাথী। বৃষ্টি, ফসল, বপন, জল নিষ্কাশন বা চাষের পরিকল্পনা সম্পর্কে জিজ্ঞাসা করুন।',Telugu:'నమస్కారం {name}! నేను మీ AI వ్యవసాయ సహచరుడిని. వర్షం, పంట, విత్తడం, నీటి పారుదల లేదా వ్యవసాయ ప్రణాళిక గురించి అడగండి.',Marathi:'नमस्कार {name}! मी तुमचा AI कृषी साथी आहे. पाऊस, पीक, पेरणी, निचरा किंवा शेती नियोजनाबद्दल विचारा.',Tamil:'வணக்கம் {name}! நான் உங்கள் AI வேளாண் துணை. மழை, பயிர், விதைப்பு, வடிகால் அல்லது விவசாயத் திட்டம் பற்றி கேளுங்கள்.'};
const AI_QUICK={English:['Will rain affect my crop?','Should I sow now?','What should I do before heavy rain?'],Odia:['ମୋ ଫସଲ ଉପରେ ବର୍ଷାର ପ୍ରଭାବ କଣ?','ଏବେ ବୁଣିବି କି?','ପ୍ରବଳ ବର୍ଷା ପୂର୍ବରୁ କଣ କରିବି?'],Hindi:['क्या बारिश मेरी फसल को प्रभावित करेगी?','क्या अभी बुवाई करूं?','भारी बारिश से पहले क्या करूं?'],Bengali:['বৃষ্টি কি আমার ফসলকে প্রভাবিত করবে?','এখন কি বপন করব?','ভারী বৃষ্টির আগে কী করব?'],Telugu:['వర్షం నా పంటపై ప్రభావం చూపుతుందా?','ఇప్పుడు విత్తాలా?','భారీ వర్షానికి ముందు ఏమి చేయాలి?'],Marathi:['पावसाचा माझ्या पिकावर परिणाम होईल का?','आता पेरणी करू का?','मुसळधार पावसापूर्वी काय करावे?'],Tamil:['மழை என் பயிரை பாதிக்குமா?','இப்போது விதைக்கலாமா?','கனமழைக்கு முன் என்ன செய்ய வேண்டும்?']};
function renderAssistant(c){const name=text(state.farmer.name,state.language==='Odia'?'ଚାଷୀ':'Farmer');if(!chat.length)chat=[{role:'ai',text:(AI_GREETING[state.language]||AI_GREETING.English).replace('{name}',name)}];const q=AI_QUICK[state.language]||AI_QUICK.English;c.innerHTML=`<div class="chat-shell"><div class="chat-head"><span>AI KRISHI SAATHI</span><h2>${tr('aiTitle')}</h2><p>${tr('aiSubhead')}</p></div><div class="chat-messages">${chat.map(m=>`<div class="bubble ${m.role==='user'?'user':'ai'}">${esc(m.text)}</div>`).join('')}</div><div class="quick-prompts"><button onclick="askAI(${JSON.stringify(q[0])})">${tr('rainCrop')}</button><button onclick="askAI(${JSON.stringify(q[1])})">${tr('sowing')}</button><button onclick="askAI(${JSON.stringify(q[2])})">${tr('heavyRain')}</button></div><div class="chat-input"><input id="ai-input" placeholder="${tr('placeholder')}"><button class="voice" id="voice-btn">●</button><button id="send-btn">↑</button></div></div>`;$('#send-btn').onclick=()=>{const i=$('#ai-input');if(i?.value.trim())askAI(i.value.trim())};$('#ai-input').onkeydown=e=>{if(e.key==='Enter'&&e.target.value.trim())askAI(e.target.value.trim())};$('#voice-btn').onclick=startVoice}
function askAI(message){chat.push({role:'user',text:message});const q=message.toLowerCase(),crop=cropFor(state.farmer.crop),w=getWeather(),know=Array.isArray(window.VARSHAMITRA_KNOWLEDGE)?window.VARSHAMITRA_KNOWLEDGE:[],hit=know.find(k=>Array.isArray(k.keywords)&&k.keywords.some(word=>q.includes(String(word).toLowerCase()))&&(!k.crop||String(k.crop).toLowerCase()===String(crop.id).toLowerCase()));let response=null;if(hit){response=state.language==='Odia'?(hit.responseOdia||hit.response):hit.response}if(!response){const rainWords=['rain','ବର୍ଷା','बारिश','বৃষ্টি','వర్ష','पाऊस','மழை'];const sowWords=['sow','sowing','plant','ବୁଣ','बुवाई','বপন','విత్త','पेरणी','விதை'];if(rainWords.some(x=>q.includes(x))){const templates={English:`Today's prototype rain probability is ${w.rainProbability}%. For ${crop.name}, monitor drainage after heavy rainfall.`,Odia:`ଆଜି ବର୍ଷା ସମ୍ଭାବନା ${w.rainProbability}%। ${crop.localName||crop.name} ପାଇଁ ପ୍ରବଳ ବର୍ଷା ପରେ ଜଳ ନିଷ୍କାସନ ଯାଞ୍ଚ କରନ୍ତୁ।`,Hindi:`आज बारिश की प्रोटोटाइप संभावना ${w.rainProbability}% है। ${crop.name} के लिए भारी बारिश के बाद जल निकासी देखें।`,Bengali:`আজ বৃষ্টির প্রোটোটাইপ সম্ভাবনা ${w.rainProbability}%। ${crop.name} এর জন্য ভারী বৃষ্টির পর জল নিষ্কাশন দেখুন।`,Telugu:`ఈరోజు వర్షం ప్రోటోటైప్ అవకాశం ${w.rainProbability}%. ${crop.name} కోసం భారీ వర్షం తర్వాత నీటి పారుదల పరిశీలించండి.`,Marathi:`आज पावसाची प्रोटोटाइप शक्यता ${w.rainProbability}% आहे. ${crop.name} साठी मुसळधार पावसानंतर निचरा तपासा.`,Tamil:`இன்றைய மழை முன்மாதிரி வாய்ப்பு ${w.rainProbability}%. ${crop.name} க்கு கனமழைக்குப் பிறகு வடிகாலை சரிபார்க்கவும்.`};response=templates[state.language]||templates.English}else if(sowWords.some(x=>q.includes(x))){const templates={English:'Before sowing, check expected rainfall, soil moisture and crop water requirement.',Odia:'ବିହନ ବୁଣିବା ପୂର୍ବରୁ ବର୍ଷା ସମୟ, ମାଟିର ଆର୍ଦ୍ରତା ଓ ଫସଲର ଜଳ ଆବଶ୍ୟକତା ଯାଞ୍ଚ କରନ୍ତୁ।',Hindi:'बुवाई से पहले अपेक्षित बारिश, मिट्टी की नमी और फसल की पानी की जरूरत जांचें।',Bengali:'বপনের আগে সম্ভাব্য বৃষ্টি, মাটির আর্দ্রতা ও ফসলের জলের প্রয়োজন দেখুন।',Telugu:'విత్తే ముందు అంచనా వర్షం, నేల తేమ మరియు పంట నీటి అవసరాన్ని పరిశీలించండి.',Marathi:'पेरणीपूर्वी अपेक्षित पाऊस, मातीतील ओलावा आणि पिकाची पाण्याची गरज तपासा.',Tamil:'விதைப்பதற்கு முன் எதிர்பார்க்கப்படும் மழை, மண் ஈரப்பதம் மற்றும் பயிரின் நீர் தேவையை சரிபார்க்கவும்.'};response=templates[state.language]||templates.English}else{const templates={English:`For ${crop.name}, the current prototype suitability is ${score(crop)}%. Tell me your field condition or plan and I can help you check it.`,Odia:`${crop.localName||crop.name} ପାଇଁ ବର୍ତ୍ତମାନର ପ୍ରୋଟୋଟାଇପ୍ ଉପଯୁକ୍ତତା ${score(crop)}%। ଆପଣଙ୍କ କ୍ଷେତର ଅବସ୍ଥା କିମ୍ବା ଯୋଜନା କହନ୍ତୁ।`,Hindi:`${crop.name} के लिए वर्तमान प्रोटोटाइप उपयुक्तता ${score(crop)}% है। अपने खेत की स्थिति या योजना बताएं।`,Bengali:`${crop.name} এর বর্তমান প্রোটোটাইপ উপযোগিতা ${score(crop)}%। আপনার খেতের অবস্থা বা পরিকল্পনা বলুন।`,Telugu:`${crop.name} కోసం ప్రస్తుత ప్రోటోటైప్ అనుకూలత ${score(crop)}%. మీ పొలం పరిస్థితి లేదా ప్రణాళిక చెప్పండి.`,Marathi:`${crop.name} साठी सध्याची प्रोटोटाइप उपयुक्तता ${score(crop)}% आहे. तुमच्या शेताची स्थिती किंवा योजना सांगा.`,Tamil:`${crop.name} க்கான தற்போதைய முன்மாதிரி பொருத்தம் ${score(crop)}%. உங்கள் வயல் நிலை அல்லது திட்டத்தைச் சொல்லுங்கள்.`};response=templates[state.language]||templates.English}}chat.push({role:'ai',text:response});renderPage('assistant')}
function startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){showToast(state.language==='Odia'?'ଏହି ବ୍ରାଉଜରରେ ଭଏସ୍ ଇନ୍ପୁଟ୍ ଉପଲବ୍ଧ ନାହିଁ।':'Voice input is not supported in this browser.');return}const r=new SR();r.lang={English:'en-IN',Odia:'or-IN',Hindi:'hi-IN',Bengali:'bn-IN',Telugu:'te-IN',Marathi:'mr-IN',Tamil:'ta-IN'}[state.language]||'en-IN';r.onstart=()=>showToast({Odia:'ଶୁଣୁଛି…',Hindi:'सुन रहा हूँ…',Bengali:'শুনছি…',Telugu:'వింటున్నాను…',Marathi:'ऐकत आहे…',Tamil:'கேட்கிறேன்…'}[state.language]||'Listening…');r.onresult=e=>{const t=e.results[0][0].transcript;$('#ai-input').value=t;askAI(t)};r.onerror=()=>showToast(state.language==='Odia'?'ଶୁଣିପାରିଲି ନାହିଁ। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।':'Could not hear that. Please try again.');r.start()}
function bind(){$$('.permission-card').forEach(x=>x.onclick=()=>requestPermission(x.dataset.permission));$('#permission-continue').onclick=()=>{state.permissions={location:true,microphone:true,notifications:true};updatePermissionUI();showScreen('language-screen')};$('#demo-permission').onclick=enterDemo;$('#permission-back').onclick=()=>showScreen('splash-screen');$$('.language-card').forEach(x=>x.onclick=()=>{$$('.language-card').forEach(y=>y.classList.remove('active'));x.classList.add('active');state.language=x.dataset.language;applyLanguage()});$('#language-back').onclick=()=>showScreen('permission-screen');$('#language-continue').onclick=()=>{saveProfile();showScreen('auth-screen');applyLanguage()};$('#farmer-form').onsubmit=e=>{e.preventDefault();state.farmer={...state.farmer,name:$('#farmer-name').value.trim()||'Farmer',location:$('#farmer-location').value.trim()||'Bhubaneswar, Odisha',crop:$('#farmer-crop').value,water:$('#farmer-water').value,soil:$('#farmer-soil').value,phone:$('#farmer-phone').value.trim()};saveProfile();openMain()};$$('.nav-item').forEach(x=>x.onclick=()=>renderPage(x.dataset.page));$('#notification-button').onclick=()=>showToast(state.language==='Odia'?'ବର୍ତ୍ତମାନ କୌଣସି ନୂଆ ବର୍ଷା ସତର୍କତା ନାହିଁ।':'No new rain alerts in this prototype.');$('#language-toggle').onclick=()=>{const order=['English','Odia','Hindi','Bengali','Telugu','Marathi','Tamil'];const i=order.indexOf(state.language);state.language=order[(i+1)%order.length];saveProfile();applyLanguage();showToast(tr('selected')+': '+LANG_META[state.language][0])}}
function showToast(m){const t=$('#toast');if(!t)return;const p=t.querySelector('p');if(p)p.textContent=m;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function start(){loadProfile();bind();applyLanguage();updatePermissionUI();setTimeout(()=>showScreen('permission-screen'),1500);setInterval(()=>{const el=$('#status-time');if(el)el.textContent=new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}).replace(' ','')},30000)}
window.VarshaMitra={state,showScreen,renderPage,askAI,requestPermission,showToast};document.addEventListener('DOMContentLoaded',start);
